-- Historical reference schema (v1.0). AUTHORITATIVE schema: src/telepathy/storage/migrations/ (K8).
PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS communities(id TEXT PRIMARY KEY, label TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Jerusalem', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), telegram_user_id TEXT, discovery_opt_in INTEGER NOT NULL DEFAULT 0 CHECK(discovery_opt_in IN (0,1)), profile_visibility TEXT NOT NULL DEFAULT 'private', created_at TEXT NOT NULL, UNIQUE(community_id,telegram_user_id));
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), platform TEXT NOT NULL, external_ref TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('PUBLIC_APPROVED','MEMBER_CONSENTED','INTERNAL_RESTRICTED','PRIVATE_UNKNOWN')), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), retention_days INTEGER NOT NULL DEFAULT 90, policy_version INTEGER NOT NULL DEFAULT 1, UNIQUE(community_id,platform,external_ref));
CREATE TABLE IF NOT EXISTS raw_events(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), dedup_key TEXT NOT NULL UNIQUE, observed_at TEXT NOT NULL, raw_json TEXT NOT NULL, processed_at TEXT);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), external_message_id TEXT NOT NULL, author_member_id TEXT REFERENCES members(id), body TEXT, event_at TEXT NOT NULL, observed_at TEXT NOT NULL, edited_at TEXT, topic_id TEXT, reply_to_id TEXT, removed_at TEXT, revision INTEGER NOT NULL DEFAULT 1, UNIQUE(source_id,external_message_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), path TEXT NOT NULL, sha256 TEXT NOT NULL, format TEXT NOT NULL, created_at TEXT NOT NULL, removed_at TEXT);
CREATE TABLE IF NOT EXISTS excerpts(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), message_id TEXT REFERENCES messages(id), document_id TEXT REFERENCES documents(id), body TEXT NOT NULL, citation_uri TEXT, valid_from TEXT NOT NULL, valid_to TEXT, content_sha256 TEXT NOT NULL, index_version INTEGER NOT NULL DEFAULT 1);
CREATE VIRTUAL TABLE IF NOT EXISTS excerpts_fts USING fts5(excerpt_id UNINDEXED, body, tokenize='unicode61 remove_diacritics 2');
CREATE TABLE IF NOT EXISTS embeddings(id TEXT PRIMARY KEY, excerpt_id TEXT NOT NULL REFERENCES excerpts(id), model_id TEXT NOT NULL, dimensions INTEGER NOT NULL, input_type TEXT NOT NULL CHECK(input_type IN ('passage','query')), policy_version INTEGER NOT NULL, content_hash TEXT NOT NULL, vector_blob BLOB NOT NULL, created_at TEXT NOT NULL, UNIQUE(excerpt_id,model_id,dimensions,input_type,policy_version));
CREATE TABLE IF NOT EXISTS consent(id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), purpose TEXT NOT NULL, granted INTEGER NOT NULL CHECK(granted IN (0,1)), granted_at TEXT, revoked_at TEXT, version INTEGER NOT NULL, UNIQUE(member_id,purpose,version));
CREATE TABLE IF NOT EXISTS skill_claims(id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), skill_code TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('suggested','confirmed','hidden','withdrawn')), evidence_excerpt_id TEXT REFERENCES excerpts(id), confirmed_at TEXT, visibility TEXT NOT NULL DEFAULT 'private', valid_to TEXT);
CREATE TABLE IF NOT EXISTS knowledge_claims(id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), statement TEXT NOT NULL, review_state TEXT NOT NULL DEFAULT 'proposed', valid_from TEXT, valid_to TEXT, supersedes_id TEXT REFERENCES knowledge_claims(id));
CREATE TABLE IF NOT EXISTS claim_evidence(claim_id TEXT NOT NULL REFERENCES knowledge_claims(id), excerpt_id TEXT NOT NULL REFERENCES excerpts(id), PRIMARY KEY(claim_id,excerpt_id));
CREATE TABLE IF NOT EXISTS needs(id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), member_id TEXT NOT NULL REFERENCES members(id), description TEXT NOT NULL, status TEXT NOT NULL, expires_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offers(id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), skill_code TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS introductions(id TEXT PRIMARY KEY, need_id TEXT NOT NULL REFERENCES needs(id), requester_id TEXT NOT NULL REFERENCES members(id), candidate_id TEXT REFERENCES members(id), status TEXT NOT NULL CHECK(status IN ('requested','candidate_selected','invited','accepted','mutually_confirmed','scheduled','completed','declined','expired','cancelled')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, invite_expires_at TEXT, UNIQUE(need_id,candidate_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, dedup_key TEXT NOT NULL UNIQUE, payload_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','leased','completed','failed','manual')), run_at TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT);
CREATE INDEX IF NOT EXISTS idx_jobs_due ON jobs(state,run_at);
CREATE TABLE IF NOT EXISTS effect_intents(id TEXT PRIMARY KEY, kind TEXT NOT NULL, target TEXT NOT NULL, payload_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','sent','uncertain','reconciled','failed')), provider_response_ref TEXT, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS release_journal(id TEXT PRIMARY KEY, generation_id TEXT NOT NULL, action TEXT NOT NULL, evidence_digest TEXT, authorized_by TEXT, at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_excerpts_source ON excerpts(source_id,valid_to);
CREATE INDEX IF NOT EXISTS idx_members_consent ON members(community_id,discovery_opt_in);
